const input = document.getElementById('username');

input.addEventListener('input', () => {
  if (input.value.length < 3) {
    input.setCustomValidity('Username must be at least 3 characters');
  } else {
    input.setCustomValidity('');
  }
  input.reportValidity();
});

function validateForm(form) {
  const inputs = [...form.elements];
  return inputs.every(el => {
    if (el.validity.valueMissing) {
      el.setCustomValidity(`${el.labels[0]?.textContent} is required`);
    }
    return el.validity.valid;
  });
}

const form = document.getElementById('myForm');
form.addEventListener('submit', async e => {
  e.preventDefault();
  const data = new FormData(form);
  const res = await fetch('/api/submit', {
    method: 'POST',
    body: data
  });
  console.log(await res.json());
});

const form = document.getElementById('search');
form.addEventListener('submit', e => {
  e.preventDefault();
  const params = new URLSearchParams(new FormData(form));
  window.location.search = '?' + params.toString();
});

const input = document.getElementById('files');
input.addEventListener('change', () => {
  const allowed = ['image/jpeg', 'image/png', 'image/webp'];
  const invalid = [...input.files].filter(f => !allowed.includes(f.type));
  if (invalid.length) {
    alert(`Invalid file types: ${invalid.map(f => f.name).join(', ')}`);
    input.value = '';
  }
});

const dropzone = document.getElementById('dropzone');
dropzone.addEventListener('dragover', e => e.preventDefault());
dropzone.addEventListener('drop', e => {
  e.preventDefault();
  const files = [...e.dataTransfer.files];
  files.forEach(file => uploadFile(file));
});

